g=[[3]*23 for _ in range(17)]
# original motif bounding r5:9,c5:10
mot=[[2,3,3,6,7],[0,4,4,2,2],[2,6,0,4,3],[3,7,7,6,3]]
# source motif bounding row5 col5
for i,row in enumerate(mot):
 for j,v in enumerate(row):
  if v!=3: g[5+i][5+j]=v
# marker coords and motif anchor rel (2,2), translated
for r,c in [(4,19),(5,13),(9,20),(13,7),(14,17)]:
 for i,row in enumerate(mot):
  for j,v in enumerate(row):
   rr=r-2+i; cc=c-2+j
   if 0<=rr<17 and 0<=cc<23 and v!=3: g[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in g))

